<script setup>
import {ref,computed,watch,onMounted} from 'vue';
import {initialData} from './seed.js';
import {generateSchedule,dramaTitle,dramaTypes,validateDrama,reschedule,announcementsForEpisode} from './schedule.js';
const key='chob-drama-private-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(key));}catch{}
const db=ref(saved?.dramas && saved?.platforms && saved?.events && saved?.changes && saved?.artists?saved:structuredClone(initialData));
const storageError=ref('');
let loaded=false;onMounted(async()=>{try{const response=await fetch('/__drama_test_data');if(!response.ok)throw Error('测试数据读取失败');db.value=await response.json();await Promise.resolve();loaded=true;}catch(e){storageError.value=e.message;}});
watch(db,async()=>{if(!loaded)return;try{const response=await fetch('/__drama_test_data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(db.value)});if(!response.ok)throw Error('测试数据保存失败');}catch(e){storageError.value=e.message;return;}try{localStorage.setItem(key,JSON.stringify(db.value));storageError.value='';}catch{storageError.value='无法保存到此浏览器，请导出备份。';}},{deep:true});
const tab=ref('library'),month=ref('2026-11'),search=ref(''),selected=ref(null),editing=ref(null),error=ref(''),notice=ref(''),eventSelected=ref(null),changeSlot=ref(null);
const changeForm=ref({date:'',time:'',content:''});
const title=dramaTitle;
function safe(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
const filtered=computed(()=>db.value.dramas.filter(d=>[d.titleZh,d.titleEn,d.titleTh,...d.types].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const slots=computed(()=>{const out=[];for(const d of db.value.dramas)for(const r of d.rules){let rows=generateSchedule(d,r);for(const c of db.value.changes.filter(c=>c.original.dramaId===d.id&&c.original.ruleId===r.id)){rows=rows.map(s=>s.id===c.original.id?c.original:s);rows.push(c.replacement);}out.push(...rows);}return out;});
const days=computed(()=>{if(!month.value)return [];const start=new Date(month.value+'-01T00:00:00Z');const count=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).getUTCDate();return [...Array((start.getUTCDay()+6)%7).fill(null),...Array.from({length:count},(_,i)=>`${month.value}-${String(i+1).padStart(2,'0')}`)];});
const notices=computed(()=>selected.value?.slot?announcementsForEpisode(db.value.changes.map(c=>c.announcement),selected.value.drama.id,selected.value.slot.episode):db.value.changes.filter(c=>c.announcement.dramaId===selected.value?.drama.id).map(c=>c.announcement));
function drama(id){return db.value.dramas.find(d=>d.id===id);}
function platform(id){return db.value.platforms.find(p=>p.id===id)||{name:id};}
function status(d){const rows=slots.value.filter(s=>s.dramaId===d.id&&s.status!=='changed');if(!rows.length)return d.production;if(rows.every(s=>s.date<new Date().toISOString().slice(0,10)))return '已完播';return rows.some(s=>s.date<=new Date().toISOString().slice(0,10))?'播出中':'待播';}
function open(d,slot=null){selected.value={drama:d,slot};}
function edit(d){editing.value=JSON.parse(JSON.stringify(d||{id:crypto.randomUUID(),titleZh:'',titleEn:'',titleTh:'',types:[],production:'未开机',poster:'',synopsis:'',cast:[],rules:[]}));error.value='';}
function addRule(){editing.value.rules.push({id:crypto.randomUUID(),platformId:'youtube',premiere:'',totalEpisodes:12,intervalDays:7,episodesPerRelease:1,time:'21:30',timezone:'Asia/Bangkok'});}
function save(){try{validateDrama(editing.value);for(const r of editing.value.rules)generateSchedule(editing.value,r);const old=db.value.dramas.find(d=>d.id===editing.value.id);if(old&&db.value.changes.some(c=>c.original.dramaId===old.id)&&JSON.stringify(old.rules)!==JSON.stringify(editing.value.rules))throw Error('已有变动历史，请通过单集变动调整排期，保留原始记录。');const i=db.value.dramas.findIndex(d=>d.id===editing.value.id);if(i<0)db.value.dramas.push(editing.value);else db.value.dramas[i]=editing.value;editing.value=null;notice.value='已保存到当前浏览器';}catch(e){error.value=e.message;}}
function applyChange(){try{const c=reschedule(changeSlot.value,changeForm.value,{id:crypto.randomUUID(),content:changeForm.value.content});db.value.changes.push(c);changeSlot.value=null;selected.value=null;}catch(e){error.value=e.message;}}
function change(s){changeSlot.value=s;changeForm.value={date:s.date,time:s.time,content:''};error.value='';}
function addCast(){editing.value.cast.push({artistId:'artist-a',name:'Artist A',role:'',lead:false});}
function exportData(){const url=URL.createObjectURL(new Blob([JSON.stringify(db.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='chob-drama-test-backup.json';a.click();URL.revokeObjectURL(url);}
function addEvent(event){const fields=event.target.elements;db.value.events.push({id:crypto.randomUUID(),name:fields.eventName.value,date:fields.eventDate.value,time:fields.eventTime.value,dramaId:fields.dramaId.value,type:fields.eventType.value});event.target.reset();}
</script>
<template>
<div class="shell"><header><a class="brand" href="#">CHOB<span>CALENDAR</span></a><span class="private">后台管理 · 隔离测试数据</span><button @click="exportData">导出备份</button></header>
<main><div class="heading"><div><p class="eyebrow">STORIES, ONE DAY AT A TIME</p><h1>Drama <em>剧集管理</em></h1><p class="muted">把每一次相遇，放进日历。</p></div><button class="primary" @click="edit()">＋ 录入剧集</button></div>
<nav><button v-for="(label,id) in {library:'剧集管理',events:'关联活动管理',platforms:'平台管理'}" :class="{active:tab===id}" @click="tab=id">{{label}}</button></nav>
<p v-if="storageError" role="alert">{{storageError}}</p><p v-if="notice" role="status">{{notice}}</p>
<section v-if="tab==='calendar'"><div class="toolbar"><input type="month" v-model="month" aria-label="月份"><span class="muted">平台当地时间 · 推算排期有单独标记</span></div><div class="calendar"><b v-for="w in ['一','二','三','四','五','六','日']" class="weekday">{{w}}</b><div v-for="(day,index) in days" :key="day||index" class="day" :class="{blank:!day}"><span class="day-number">{{day?Number(day.slice(-2)):''}}</span><template v-if="day"><button v-for="s in slots.filter(s=>s.date===day)" :key="s.id" class="chip" :class="{changed:s.status==='changed'}" @click="open(drama(s.dramaId),s)"><span :class="{strike:s.status==='changed'}">{{title(drama(s.dramaId))}} · EP.{{s.episode}}</span><small>{{s.status==='changed'?'剧集变动':`${s.time} · ${platform(s.platformId).name}`}}{{s.confidence==='calculated'?' · 推算':''}}</small></button><button v-for="e in db.events.filter(e=>e.date===day)" class="chip event" @click="eventSelected=e">{{e.type}}<small>{{e.name}}</small></button></template></div></div></section>
<section v-if="tab==='library'"><div class="toolbar"><input v-model="search" placeholder="搜索剧名、类型" aria-label="搜索剧集"><span>{{filtered.length}} 部剧集</span></div><div class="cards"><article v-for="d in filtered" :key="d.id" class="card"><button class="card-main" @click="open(d)"><img v-if="safe(d.poster)" :src="safe(d.poster)" alt="剧集海报"><div v-else class="poster">CHOB<br>DRAMA</div><div><span class="badge">{{status(d)}}</span><h2>{{title(d)}}</h2><p>{{d.titleEn}}</p><p class="muted">{{d.types.join(' · ')}}</p><p>主演：{{d.cast.filter(c=>c.lead).map(c=>c.name).join('、')||'待公布'}}</p></div></button><button @click="edit(d)">编辑资料</button></article></div><p v-if="!filtered.length">暂无匹配剧集</p></section>
<section v-if="tab==='events'"><h2>Calendar · 关联活动</h2><p class="muted">这里展示隔离的活动资料，可从活动返回剧集详情。</p><article class="event-row" v-for="e in db.events"><span>{{e.date}} {{e.time}}</span><button @click="eventSelected=e">{{e.name}}</button><button @click="open(drama(e.dramaId))">查看关联剧集 ↗</button></article><form class="panel" @submit.prevent="addEvent($event)"><h3>新增关联活动</h3><input name="eventName" required placeholder="活动名称"><input name="eventDate" type="date" required><input name="eventTime" type="time" required><select name="eventType"><option>Press Tour</option><option>观影活动</option><option>首映礼</option></select><select name="dramaId" required><option v-for="d in db.dramas" :value="d.id">{{title(d)}}</option></select><button class="primary">保存活动</button></form></section>
<section v-if="tab==='platforms'"><h2>平台行内图标</h2><div class="event-row" v-for="p in db.platforms"><label>名称<input v-model="p.name"></label><label>Logo 图片链接<input v-model="p.logo" type="url" placeholder="https://…"></label><span class="platform"><img v-if="safe(p.logo)" :src="safe(p.logo)" alt="">{{p.name}}</span></div><p class="muted">图标高 16px，保持原始比例。请使用平台官方图片链接。</p></section>
</main>
<div v-if="selected" class="overlay" @click.self="selected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="剧集详情" tabindex="-1" @keydown.esc="selected=null"><button class="close" @click="selected=null">关闭 ×</button><div class="hero"><img v-if="safe(selected.drama.poster)" :src="safe(selected.drama.poster)" alt="剧集海报"><div v-if="selected.slot?.status==='changed'" class="banner"><strong>剧集变动</strong><span>{{notices.find(n=>n.id===selected.slot.announcementId)?.content}}</span></div></div><span class="badge">{{status(selected.drama)}}</span><h2>{{title(selected.drama)}}</h2><p>{{selected.drama.types.join(' · ')}}</p><p>{{selected.drama.synopsis}}</p><h3 v-if="selected.slot">EP.{{selected.slot.episode}} · {{selected.slot.date}}</h3><p v-if="selected.slot" class="platform"><img v-if="safe(platform(selected.slot.platformId).logo)" :src="safe(platform(selected.slot.platformId).logo)" alt="">{{platform(selected.slot.platformId).name}} · {{selected.slot.time}} · {{selected.slot.timezone}} <small>{{selected.slot.confidence==='calculated'?'系统推算':'已确认'}}</small></p><button v-if="selected.slot?.status==='scheduled'" @click="change(selected.slot)">调整本集排播</button><aside v-for="n in notices" class="announcement"><strong>剧集变动 · EP.{{n.affectedEpisodes.join('、')}}</strong><p>{{n.content}}</p><small>原定 {{n.originalDate}} → 调整后 {{n.updatedDate}}</small></aside><h3>卡司与角色</h3><p v-for="c in selected.drama.cast">{{c.name}} 饰 {{c.role||'待公布'}} {{c.lead?'· 主演':''}}</p><a v-if="safe(selected.drama.source)" :href="safe(selected.drama.source)" target="_blank" rel="noopener noreferrer">官方来源 ↗</a><h3>Press Tour / 观影活动</h3><button v-for="e in db.events.filter(e=>e.dramaId===selected.drama.id)" class="event-row" @click="eventSelected=e">{{e.date}} · {{e.name}} ↗ Calendar</button></section></div>
<div v-if="editing" class="overlay" @click.self="editing=null"><form class="dialog editor" @submit.prevent="save"><button type="button" class="close" @click="editing=null">取消 ×</button><h2>剧集录入</h2><p class="muted">三种剧名至少填写一项；没有明确首播日期时只进入剧集库。</p><label v-for="(label,k) in {titleZh:'中文名',titleEn:'英文名',titleTh:'泰语名',poster:'海报图片链接',source:'官方来源链接'}">{{label}}<input v-model="editing[k]"></label><label>简介<textarea v-model="editing.synopsis"></textarea></label><fieldset><legend>类型</legend><label v-for="t in dramaTypes" class="inline"><input type="checkbox" v-model="editing.types" :value="t">{{t}}</label></fieldset><label>制作进度<select v-model="editing.production"><option>未开机</option><option>已开机</option><option>已杀青</option></select></label><h3>卡司</h3><div class="panel" v-for="(c,i) in editing.cast"><select v-model="c.artistId" @change="c.name=db.artists.find(a=>a.id===c.artistId)?.name"><option v-for="a in db.artists" :value="a.id">{{a.name}}</option></select><input v-model="c.role" placeholder="角色名称"><label class="inline"><input type="checkbox" v-model="c.lead">主演</label><button type="button" @click="editing.cast.splice(i,1)">移除</button></div><button type="button" @click="addCast">＋ 卡司</button><h3>播出安排</h3><div class="panel" v-for="(r,i) in editing.rules"><label>平台<select v-model="r.platformId"><option v-for="p in db.platforms" :value="p.id">{{p.name}}</option></select></label><label>首播日期<input type="date" v-model="r.premiere"></label><label>总集数<input type="number" min="1" max="1000" v-model.number="r.totalEpisodes"></label><label>每隔几天更新<input type="number" min="1" max="1000" v-model.number="r.intervalDays"></label><label>每次更新集数<input type="number" min="1" max="1000" v-model.number="r.episodesPerRelease"></label><label>播出时间<input type="time" v-model="r.time"></label><label>时区<select v-model="r.timezone"><option>Asia/Bangkok</option><option>Asia/Shanghai</option><option>UTC</option></select></label><button type="button" @click="editing.rules.splice(i,1)">移除此平台排期</button></div><button type="button" @click="addRule">＋ 平台排期</button><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary">保存并自动排播</button></form></div>
<div v-if="changeSlot" class="overlay"><form class="dialog editor" @submit.prevent="applyChange"><button type="button" class="close" @click="changeSlot=null">取消 ×</button><h2>调整 EP.{{changeSlot.episode}}</h2><p>原日期记录将保留并划线，公告显示在本集及前后集。</p><label>新日期<input type="date" v-model="changeForm.date" required></label><label>新时间<input type="time" v-model="changeForm.time" required></label><label>变动说明<textarea v-model="changeForm.content" required></textarea></label><p class="error" role="alert">{{error}}</p><button class="primary">保存变动公告</button></form></div>
<div v-if="eventSelected" class="overlay" @click.self="eventSelected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="Calendar 活动详情"><button class="close" @click="eventSelected=null">关闭 ×</button><p class="eyebrow">CALENDAR · {{eventSelected.type}}</p><h2>{{eventSelected.name}}</h2><p>{{eventSelected.date}} {{eventSelected.time}}</p><p>{{eventSelected.location}}</p><button @click="open(drama(eventSelected.dramaId));eventSelected=null">查看关联剧集 ↗</button></section></div>
<footer>CHOB CALENDAR · DRAMA V1 <span>隔离预览 / 非正式数据</span></footer></div>
</template>
<style scoped>
*{box-sizing:border-box}body{margin:0;background:#faf9f6;color:#303b35;font:15px/1.6 system-ui,-apple-system,'Microsoft YaHei',sans-serif}button,input,select,textarea{font:inherit}button,a{cursor:pointer}button{border:1px solid #d9ded7;background:white;border-radius:8px;padding:8px 14px;color:inherit}button:hover{background:#e9eee7}input,select,textarea{border:1px solid #d9ded7;border-radius:7px;padding:9px;background:white;max-width:100%}textarea{min-height:85px}header{display:flex;gap:20px;align-items:center;padding:24px 5%;border-bottom:1px solid #e4e5dd}.brand{font-size:25px;font-weight:800;letter-spacing:3px;text-decoration:none;color:#3f5848}.brand span{display:block;font-size:9px;letter-spacing:4px}.private{margin-left:auto;font-size:12px;color:#777}main{max-width:1280px;margin:auto;padding:40px 30px}.heading{display:flex;justify-content:space-between;align-items:center}.eyebrow{font-size:11px;letter-spacing:3px;color:#86927d}h1{font-size:44px;margin:8px 0;font-family:Georgia,serif}h1 em{font:normal 21px system-ui;margin-left:12px;color:#89957d}h2{font-size:23px}h3{font-size:17px}.muted,small{color:#7d857d}.primary{background:#4e664d;color:white;border-color:#4e664d}.primary:hover{background:#3c503c}nav{display:flex;gap:22px;border-bottom:1px solid #dfe3da;margin:30px 0}nav button{border:0;border-radius:0;background:none;padding:14px 4px}.active{border-bottom:3px solid #4e664d!important;font-weight:700}.toolbar{display:flex;justify-content:space-between;gap:16px;margin:20px 0}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-top:1px solid #e1e5dc;border-left:1px solid #e1e5dc;background:white}.weekday{text-align:center;font-weight:400;padding:12px;background:#f1f3ed}.day{min-height:150px;border-right:1px solid #e1e5dc;border-bottom:1px solid #e1e5dc;padding:8px}.blank{background:#f7f7f3}.day-number{font-size:13px;color:#8b9288}.chip{display:block;width:100%;text-align:left;padding:7px;margin:5px 0;font-size:12px;background:#edf2e9;border:0;border-left:3px solid #8ca37b;border-radius:4px}.chip small{display:block;font-size:10px}.changed{background:#f7e9e2;border-color:#c69077}.strike{text-decoration:line-through}.event{background:#f1ecf7;border-color:#a48cbf}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}.card{background:white;padding:18px;border:1px solid #e1e5dc;border-radius:12px}.card-main{display:flex;gap:22px;text-align:left;width:100%;border:0;padding:0;background:none}.card-main img,.poster{width:115px;height:160px;object-fit:cover;border-radius:6px;flex-shrink:0}.poster{background:linear-gradient(145deg,#bdcbb4,#758d75);color:white;display:grid;place-content:center;text-align:center;font:20px Georgia;letter-spacing:3px}.badge{font-size:11px;background:#edf1e6;padding:4px 9px;border-radius:20px}.card h2{font-size:20px;margin:10px 0}.card p{font-size:12px;margin:5px 0}.card>button:last-child{margin-top:12px;font-size:12px}.overlay{position:fixed;inset:0;background:#16261f66;display:flex;align-items:center;justify-content:center;z-index:10;padding:24px}.dialog{position:relative;background:#faf9f6;border-radius:14px;padding:32px;width:650px;max-height:90vh;overflow:auto;box-shadow:0 20px 80px #14271d44}.close{float:right}.hero{position:relative;clear:both}.hero img{width:100%;max-height:280px;object-fit:contain}.banner{background:#f0d9c9;padding:16px;margin:18px 0}.banner strong{display:block;font-size:18px}.banner span{font-size:15px}.announcement{background:#f3e8db;border-radius:8px;padding:15px;margin:15px 0}.announcement p{margin:7px 0}.platform{display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap}.platform img{height:16px;width:auto;max-width:70px;object-fit:contain}.editor label{display:flex;flex-direction:column;gap:5px;margin:12px 0}.editor .inline{display:inline-flex;flex-direction:row;margin-right:14px;align-items:center}.editor input[type=checkbox]{width:auto}.panel{border:1px solid #dce2d7;padding:15px;border-radius:8px;margin:15px 0}.panel input,.panel select{margin:5px}.event-row{display:flex;align-items:center;gap:14px;flex-wrap:wrap;width:100%;padding:18px;border-bottom:1px solid #dce2d7}.event-row label{display:flex;flex-direction:column}.error{color:#a33e29}footer{padding:25px 5%;border-top:1px solid #e1e5dc;font-size:11px;letter-spacing:2px;color:#8b9288}footer span{float:right}@media(max-width:700px){main{padding:20px 12px}.private{font-size:10px}header{gap:8px;padding:15px}.heading{align-items:start}h1{font-size:30px}h1 em{display:block;margin:0;font-size:17px}.cards{grid-template-columns:1fr}.calendar{min-width:700px}section:has(>.calendar){overflow:auto}.day{min-height:120px}nav{gap:10px}nav button{font-size:13px}.dialog{padding:22px}.toolbar{font-size:11px}.overlay{padding:10px}}
</style>

